        self.wr(5,str(a)); time.sleep(0.3)
    def status(self):
        return self.p[9].latest()
    def radio_send(self,s): self.wr(8,s)
    def radio_recv(self):
        self.p[3].poll(); q=self.p[3].queue[:]; self.p[3].queue.clear(); return q
