        # relative: front,left,back,right min-triples
        def trip(c): return min(s[(c-1)%16],s[c],s[(c+1)%16])
        return {0:trip(0),90:trip(4),180:trip(8),270:trip(12)}
    def face(self,d):
        if d!=self.facing or True:
            spin_to(self.b,d)
        self.facing=d
